SQL = r"""
-- Add provenance to historical workflow events without rewriting their payloads.
DROP TRIGGER cms_workflow_transition_append_only ON cms_contentworkflowtransition;
UPDATE cms_contentworkflowtransition t SET revision_id=(
 SELECT r.id FROM cms_contentrevision r WHERE r.content_id=t.content_id
 AND r.status=t.to_status AND r.created_at<=t.created_at ORDER BY r.revision_number DESC LIMIT 1);
UPDATE cms_contentworkflowtransition t SET reviewed_revision_id=(
 SELECT prior.id FROM cms_contentrevision prior JOIN cms_contentrevision approved ON approved.id=t.revision_id
 WHERE prior.content_id=t.content_id AND prior.revision_number=approved.revision_number-1 AND prior.status='IN_REVIEW')
 WHERE t.to_status='APPROVED';
-- Flush deferred FK events from the backfill before schema_editor builds the
-- new FK indexes at migration exit (important on databases with real history).
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
CREATE TRIGGER cms_workflow_transition_append_only BEFORE UPDATE OR DELETE ON cms_contentworkflowtransition
 FOR EACH ROW EXECUTE FUNCTION cms_reject_history_mutation();

CREATE FUNCTION cms_visual_approval_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE approved cms_contentrevision; reviewed cms_contentrevision; current_rev integer; visual boolean;
BEGIN
 SELECT revision_number,metadata ? 'visual_layout' INTO current_rev,visual FROM cms_sitecontent WHERE id=NEW.content_id;
 IF NEW.to_status='APPROVED' AND visual THEN
  SELECT * INTO approved FROM cms_contentrevision WHERE id=NEW.revision_id;
  SELECT * INTO reviewed FROM cms_contentrevision WHERE id=NEW.reviewed_revision_id;
  IF approved.id IS NULL OR reviewed.id IS NULL OR approved.content_id<>NEW.content_id OR reviewed.content_id<>NEW.content_id
   OR approved.status<>'APPROVED' OR reviewed.status<>'IN_REVIEW' OR approved.revision_number<>current_rev
   OR reviewed.revision_number<>approved.revision_number-1
   OR (approved.snapshot-ARRAY['status','published_at','review_comment']) IS DISTINCT FROM (reviewed.snapshot-ARRAY['status','published_at','review_comment']) THEN
   RAISE EXCEPTION 'Approval must bind the reviewed visual revision.' USING ERRCODE='23514',CONSTRAINT='cms_visual_approval_revision';
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER cms_visual_approval_revision_guard BEFORE INSERT ON cms_contentworkflowtransition
 FOR EACH ROW EXECUTE FUNCTION cms_visual_approval_revision_guard();

CREATE FUNCTION cms_visual_publication_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE a cms_contentworkflowtransition; r cms_contentrevision; source cms_sitecontent; key text;
BEGIN
 IF NOT (NEW.payload->'metadata') ? 'visual_layout' THEN RETURN NEW; END IF;
 SELECT * INTO a FROM cms_contentworkflowtransition WHERE id=NEW.approval_id;
 SELECT * INTO r FROM cms_contentrevision WHERE id=NEW.approved_revision_id;
 SELECT * INTO source FROM cms_sitecontent WHERE id=a.content_id;
 IF a.id IS NULL OR r.id IS NULL OR a.to_status<>'APPROVED' OR a.revision_id<>r.id OR r.content_id<>a.content_id OR r.status<>'APPROVED'
  OR source.site_id::text IS DISTINCT FROM NEW.payload->>'site_id'
  OR NOT ((source.id=NEW.content_id AND source.status='PUBLISHED' AND source.revision_number=r.revision_number+1)
   OR (source.status='APPROVED' AND source.revision_number=r.revision_number AND EXISTS(SELECT 1 FROM cms_page WHERE sitecontent_ptr_id=source.id AND draft_of_id=NEW.content_id))) THEN
  RAISE EXCEPTION 'Publication requires its exact approved revision.' USING ERRCODE='23514',CONSTRAINT='cms_visual_publication_approval';
 END IF;
 FOREACH key IN ARRAY ARRAY['title','blocks','blocks_version','metadata','layout','seo','visibility','locale'] LOOP
  IF NEW.payload->key IS DISTINCT FROM r.snapshot->key THEN
   RAISE EXCEPTION 'Publication presentation differs from approval.' USING ERRCODE='23514',CONSTRAINT='cms_visual_publication_payload';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;
CREATE TRIGGER cms_visual_publication_revision_guard BEFORE INSERT ON cms_publishedcontentsnapshot
 FOR EACH ROW EXECUTE FUNCTION cms_visual_publication_revision_guard();
"""
